'use client';

import React, { useState } from 'react';
import { Calculator, Zap, TrendingUp, Clock, DollarSign, ArrowRight, Sparkles } from 'lucide-react';

interface RoiCalculatorProps {
  onOpenContact: () => void;
}

export default function RoiCalculator({ onOpenContact }: RoiCalculatorProps) {
  const [teamSize, setTeamSize] = useState<number>(5);
  const [hoursPerWeek, setHoursPerWeek] = useState<number>(10);
  const [hourlyRate, setHourlyRate] = useState<number>(40);
  const [currency, setCurrency] = useState<'USD' | 'INR'>('USD');

  // Multiplier for currency
  const currencySymbol = currency === 'USD' ? '$' : '₹';
  const rateMultiplier = currency === 'USD' ? 1 : 25; // Approx converted rate for INR display

  // Calculations
  const effectiveRate = hourlyRate * (currency === 'USD' ? 1 : 25);
  const weeklyHoursWasted = teamSize * hoursPerWeek;
  const monthlyHoursReclaimed = Math.round(weeklyHoursWasted * 4.2 * 0.75); // 75% automation recovery
  const annualHoursReclaimed = monthlyHoursReclaimed * 12;
  const annualSavings = Math.round(annualHoursReclaimed * effectiveRate);

  return (
    <section id="roi-calculator" style={{ padding: '100px 0', position: 'relative' }}>
      <div className="container-custom">
        <div style={{ textAlign: 'center', maxWidth: '780px', margin: '0 auto 50px' }}>
          <div style={{ display: 'inline-flex', marginBottom: '16px' }}>
            <span className="badge-pill">
              <Calculator size={14} />
              <span>Interactive ROI Estimator</span>
            </span>
          </div>
          <h2
            className="font-serif"
            style={{
              fontSize: 'clamp(2rem, 4vw, 3rem)',
              fontWeight: 800,
              letterSpacing: '-0.02em',
              marginBottom: '16px',
            }}
          >
            How Much Time &amp; Capital Can <span className="gradient-text-orange">AI Automation Save You?</span>
          </h2>
          <p style={{ color: 'var(--text-secondary)', fontSize: '1.05rem', lineHeight: 1.6 }}>
            Adjust the sliders below to estimate your company&apos;s annual savings and reclaimed bandwidth through Hafeez Studio&apos;s custom AI agent systems.
          </p>
        </div>

        <div
          className="glass-card"
          style={{
            maxWidth: '1060px',
            margin: '0 auto',
            padding: '40px',
            border: '1px solid rgba(255, 94, 30, 0.25)',
          }}
        >
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
              gap: '48px',
              alignItems: 'center',
            }}
          >
            {/* Input Sliders */}
            <div>
              {/* Currency Toggle */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '28px' }}>
                <span style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>
                  Select Currency
                </span>
                <div style={{ display: 'flex', gap: '6px', background: 'rgba(255,255,255,0.05)', padding: '4px', borderRadius: '8px' }}>
                  <button
                    onClick={() => setCurrency('USD')}
                    style={{
                      padding: '4px 12px',
                      borderRadius: '6px',
                      border: 'none',
                      fontSize: '0.8rem',
                      fontWeight: 600,
                      background: currency === 'USD' ? 'var(--accent-orange)' : 'transparent',
                      color: '#FFFFFF',
                      cursor: 'pointer',
                    }}
                  >
                    USD ($)
                  </button>
                  <button
                    onClick={() => setCurrency('INR')}
                    style={{
                      padding: '4px 12px',
                      borderRadius: '6px',
                      border: 'none',
                      fontSize: '0.8rem',
                      fontWeight: 600,
                      background: currency === 'INR' ? 'var(--accent-orange)' : 'transparent',
                      color: '#FFFFFF',
                      cursor: 'pointer',
                    }}
                  >
                    INR (₹)
                  </button>
                </div>
              </div>

              {/* Slider 1: Team Size */}
              <div style={{ marginBottom: '32px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                  <label style={{ fontSize: '0.9rem', fontWeight: 600, color: 'var(--text-primary)' }}>
                    Team Members in Operations / Sales
                  </label>
                  <span style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--accent-orange)' }}>
                    {teamSize} people
                  </span>
                </div>
                <input
                  type="range"
                  min={1}
                  max={50}
                  value={teamSize}
                  onChange={(e) => setTeamSize(Number(e.target.value))}
                  style={{
                    width: '100%',
                    accentColor: 'var(--accent-orange)',
                    cursor: 'pointer',
                  }}
                />
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: '4px' }}>
                  <span>1 person</span>
                  <span>25 people</span>
                  <span>50 people</span>
                </div>
              </div>

              {/* Slider 2: Manual Hours */}
              <div style={{ marginBottom: '32px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                  <label style={{ fontSize: '0.9rem', fontWeight: 600, color: 'var(--text-primary)' }}>
                    Manual/Repetitive Hours / Person / Week
                  </label>
                  <span style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--accent-orange)' }}>
                    {hoursPerWeek} hrs/wk
                  </span>
                </div>
                <input
                  type="range"
                  min={2}
                  max={25}
                  value={hoursPerWeek}
                  onChange={(e) => setHoursPerWeek(Number(e.target.value))}
                  style={{
                    width: '100%',
                    accentColor: 'var(--accent-orange)',
                    cursor: 'pointer',
                  }}
                />
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: '4px' }}>
                  <span>2 hrs (Low)</span>
                  <span>12 hrs (Medium)</span>
                  <span>25 hrs (Heavy)</span>
                </div>
              </div>

              {/* Slider 3: Hourly Value */}
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                  <label style={{ fontSize: '0.9rem', fontWeight: 600, color: 'var(--text-primary)' }}>
                    Estimated Team Hourly Value / Cost
                  </label>
                  <span style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--accent-orange)' }}>
                    {currencySymbol}{currency === 'USD' ? hourlyRate : hourlyRate * 25}/hr
                  </span>
                </div>
                <input
                  type="range"
                  min={15}
                  max={150}
                  step={5}
                  value={hourlyRate}
                  onChange={(e) => setHourlyRate(Number(e.target.value))}
                  style={{
                    width: '100%',
                    accentColor: 'var(--accent-orange)',
                    cursor: 'pointer',
                  }}
                />
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: '4px' }}>
                  <span>{currencySymbol}{currency === 'USD' ? 15 : 15 * 25}</span>
                  <span>{currencySymbol}{currency === 'USD' ? 80 : 80 * 25}</span>
                  <span>{currencySymbol}{currency === 'USD' ? 150 : 150 * 25}+</span>
                </div>
              </div>
            </div>

            {/* Results Display */}
            <div
              style={{
                background: 'linear-gradient(145deg, rgba(255, 94, 30, 0.08) 0%, rgba(18, 18, 22, 0.95) 100%)',
                border: '1px solid rgba(255, 94, 30, 0.35)',
                borderRadius: 'var(--radius-lg)',
                padding: '36px',
                textAlign: 'center',
                boxShadow: '0 20px 40px rgba(0, 0, 0, 0.5)',
              }}
            >
              <div style={{ fontSize: '0.85rem', textTransform: 'uppercase', letterSpacing: '0.12em', color: 'var(--accent-orange)', fontWeight: 700, marginBottom: '8px' }}>
                Estimated Annual Value Unlocked
              </div>
              <div
                className="font-serif gradient-text-orange"
                style={{
                  fontSize: 'clamp(2.5rem, 5vw, 3.8rem)',
                  fontWeight: 900,
                  lineHeight: 1.1,
                  marginBottom: '16px',
                }}
              >
                {currencySymbol}{annualSavings.toLocaleString()}
                <span style={{ fontSize: '1rem', color: 'var(--text-secondary)', fontWeight: 400, marginLeft: '6px' }}>/ year</span>
              </div>

              {/* Secondary Stats */}
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: '1fr 1fr',
                  gap: '16px',
                  margin: '24px 0',
                  padding: '20px 0',
                  borderTop: '1px solid var(--border-subtle)',
                  borderBottom: '1px solid var(--border-subtle)',
                }}
              >
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px', color: '#34D399', fontSize: '0.78rem', fontWeight: 600, marginBottom: '4px' }}>
                    <Clock size={14} />
                    Monthly Bandwidth Saved
                  </div>
                  <div style={{ fontSize: '1.4rem', fontWeight: 800, color: '#FFFFFF' }}>
                    ~{monthlyHoursReclaimed} hrs
                  </div>
                </div>

                <div>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px', color: '#F59E0B', fontSize: '0.78rem', fontWeight: 600, marginBottom: '4px' }}>
                    <Zap size={14} />
                    Lead Response Time
                  </div>
                  <div style={{ fontSize: '1.4rem', fontWeight: 800, color: '#FFFFFF' }}>
                    &lt; 5 seconds
                  </div>
                </div>
              </div>

              <p style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginBottom: '24px' }}>
                Based on an average 75% automation recovery rate across sales qualification, CRM processing, and customer ticket deflection.
              </p>

              <button
                onClick={onOpenContact}
                className="btn-primary"
                style={{ width: '100%', padding: '16px', fontSize: '0.95rem' }}
              >
                <span>Claim These Savings with Hafeez Studio</span>
                <ArrowRight size={16} />
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
